package com.yazaki.printingservice.application;
import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import com.yazaki.printingservice.api.dto.PrinterDtos; import com.yazaki.printingservice.api.error.*; import com.yazaki.printingservice.domain.model.*; import com.yazaki.printingservice.domain.repository.PrinterRepository;
@Service
public class PrinterService {
 private final PrinterRepository repository; public PrinterService(PrinterRepository repository){this.repository=repository;}
 @Transactional public PrinterDtos.View create(PrinterDtos.Upsert in){if(repository.findByCode(in.code()).isPresent())throw new ConflictException("Printer code already exists");var p=new Printer(in.code(),in.name(),in.type());apply(p,in.name(),in.type(),in.location(),in.technicalConfiguration(),in.status(),in.cupsQueueName());if(Boolean.FALSE.equals(in.enabled()))p.deactivate();return view(repository.save(p));}
 @Transactional public PrinterDtos.View replace(UUID id,PrinterDtos.Upsert in){var p=entity(id);if(!p.getCode().equals(in.code()))throw new BusinessRuleException("Printer code is immutable");apply(p,in.name(),in.type(),in.location(),in.technicalConfiguration(),in.status(),in.cupsQueueName());if(Boolean.FALSE.equals(in.enabled()))p.deactivate();else p.activate();return view(p);}
 @Transactional public PrinterDtos.View patch(UUID id,PrinterDtos.Patch in){var p=entity(id);apply(p,in.name()==null?p.getName():in.name(),in.type()==null?p.getType():in.type(),in.location()==null?p.getLocation():in.location(),in.technicalConfiguration()==null?p.getTechnicalConfiguration():in.technicalConfiguration(),in.status()==null?p.getStatus():in.status(),in.cupsQueueName()==null?p.getCupsQueueName():in.cupsQueueName());return view(p);}
 @Transactional public PrinterDtos.View enabled(UUID id,boolean enabled){var p=entity(id);if(enabled)p.activate();else p.deactivate();return view(p);}
 @Transactional(readOnly=true) public PrinterDtos.View get(UUID id){return view(entity(id));}
 @Transactional(readOnly=true) public Page<PrinterDtos.View> search(String search,PrinterType type,PrinterStatus status,Boolean enabled,Pageable page){Specification<Printer>s=(r,q,b)->b.conjunction();if(search!=null&&!search.isBlank()){String x="%"+search.toLowerCase()+"%";s=s.and((r,q,b)->b.or(b.like(b.lower(r.get("name")),x),b.like(b.lower(r.get("code")),x)));}if(type!=null)s=s.and((r,q,b)->b.equal(r.get("type"),type));if(status!=null)s=s.and((r,q,b)->b.equal(r.get("status"),status));if(enabled!=null)s=s.and((r,q,b)->b.equal(r.get("enabled"),enabled));return repository.findAll(s,page).map(this::view);}
 private void apply(Printer p,String n,PrinterType t,String l,String c,PrinterStatus s,String q){if(t==PrinterType.LABEL&&q!=null&&!q.isBlank())throw new BusinessRuleException("cupsQueueName is only applicable to DOCUMENT printers");p.update(n,t,l,c,s,q);}
 private Printer entity(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Printer not found"));}
 public PrinterDtos.View view(Printer p){return new PrinterDtos.View(p.getId(),p.getCode(),p.getName(),p.getType(),p.getLocation(),p.getTechnicalConfiguration(),p.getStatus(),p.isEnabled(),p.getCupsQueueName(),p.getCreatedAt(),p.getUpdatedAt());}
}
